const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon(
    [[[-8.40, 39.80],
      [-8.40, 40.10],
      [-8.10, 40.10],
      [-8.10, 39.80],
      [-8.40, 39.80]]]); // Bounding box around Pedrógão Grande area
  const startDate = '2017-06-16';
  const endDate = '2017-06-21'; // End date is exclusive in filterDate

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(geometry);

  const initialSize = await collection.size().getInfo();
  if (initialSize === 0) {
    console.log("No MODIS/MOD14A1 images found for the specified date range and location.");
    console.log("C1");
    return;
  }
  console.log(`Initial images found: ${initialSize}`);

  // 3. Processing: Filter for high confidence fire pixels
  // FireMask values: 7, 8, 9 indicate high confidence fire.
  // Pixels with FireMask <= 6 are not high confidence fires.
  const firePixels = collection.map(image =>
    image.select('FireMask').gte(7).rename('fire_detection')
  );

  // Combine all fire detections over the period into a single image
  // Any pixel that was detected as fire at least once will be 1, otherwise 0.
  const combinedFires = firePixels.reduce(ee.Reducer.max());

  // 4. Calculation: Count valid fire pixels
  // Use a relatively large scale to avoid timeout errors for regional reductions.
  const firePixelCount = await combinedFires.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000, // MODIS resolution is ~1km, so 1000m scale is appropriate
    maxPixels: 1e9
  }).get('fire_detection').getInfo();

  // 5. Validation & Final Answer
  if (firePixelCount === null || typeof firePixelCount === 'undefined') {
    console.log("Calculation failed: Fire pixel count is null or undefined.");
    console.log("C3");
    return;
  }

  // Check if any fire pixels were detected (count > 0)
  if (firePixelCount > 0) {
    console.log(`Total high-confidence fire pixels detected: ${firePixelCount}`);
    console.log("A");
  } else {
    console.log(`Total high-confidence fire pixels detected: ${firePixelCount}`);
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
